// Compares, by caregiver ID only, who the old sheet workflow texted for the service date
// with who the new reminders service would text. Reads no names, phones or client fields.
// The sheet node continues on error after its retries; say so instead of comparing nothing.
const firstJson = ($input.first() || { json: {} }).json;
if (firstJson.error !== undefined && firstJson['Employee UID'] === undefined) {
  const msg = typeof firstJson.error === 'string' ? firstJson.error : (firstJson.error && firstJson.error.message) || 'unknown error';
  const e = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  return [{ json: {
    subject: '[RAH Reminders] Compare FAILED: could not read the old reminders sheet',
    html: "<div style='font-family:Arial,Helvetica,sans-serif;max-width:560px;'><p>The old reminders sheet could not be read after 3 tries, so there is no comparison today.</p><p>" + e(msg) + "</p><p style='font-size:12px;color:#6b7280;'>Execution " + e($execution.id) + '. No names, phone numbers or message text.</p></div>',
  } }];
}

const run = $('Run Dry Run').first().json;
const date = run.serviceDate;
const planned = Array.isArray(run.plannedCaregiverUids) ? run.plannedCaregiverUids : null;
const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Old side: per caregiver ID, what the sheet says for this date.
const old = {};
let rowsForDate = 0;
for (const item of $input.all()) {
  const r = item.json;
  if (String(r['Visit Start Date'] || '') !== date) continue;
  const uid = String(r['Employee UID'] || '').trim();
  const status = String(r['text status'] || '').trim();
  rowsForDate += 1;
  if (!uid) continue;
  const o = old[uid] || (old[uid] = { texted: false, error: false, blank: false });
  if (!status) o.blank = true;
  else if (status.toUpperCase().startsWith('ERROR')) o.error = true;
  else o.texted = true;
}
const oldTexted = Object.keys(old).filter((u) => old[u].texted).sort();

// New side: why the service would not text someone, from its exceptions (IDs only).
const newReason = {};
for (const e of run.exceptions || []) {
  if (e.caregiverUid && !newReason[e.caregiverUid]) newReason[e.caregiverUid] = e.reason;
}

const NEW_REASONS = {
  inactive_caregiver: 'not active in AlayaCare',
  no_phone: 'no phone in AlayaCare',
  invalid_phone: 'phone not a valid mobile in AlayaCare',
};
let onlyOld = [];
let onlyNew = [];
if (planned) {
  const p = new Set(planned);
  const o = new Set(oldTexted);
  onlyOld = oldTexted.filter((u) => !p.has(u)).map((u) => ({
    uid: u,
    why: newReason[u] ? 'new: ' + (NEW_REASONS[newReason[u]] || newReason[u]) : 'new: no visit for this caregiver, or ID excluded',
  }));
  onlyNew = planned.filter((u) => !o.has(u)).map((u) => {
    const s = old[u];
    const why = !s ? 'old: no row in the sheet for this date' : s.error ? 'old: marked ERROR' : 'old: row not processed';
    return { uid: u, why };
  });
}

const same = planned ? planned.length - onlyNew.length : 0;
const shortDay = date ? new Date(date + 'T12:00:00Z').toLocaleDateString('en-CA', { timeZone: 'UTC', month: 'short', day: 'numeric' }) : '';
const subject = !planned
  ? '[RAH Reminders] Compare ' + shortDay + ': not available (service has no ID list yet)'
  : '[RAH Reminders] Compare ' + shortDay + ': ' + (onlyOld.length + onlyNew.length === 0 ? 'match' : onlyOld.length + ' only old, ' + onlyNew.length + ' only new');
const td = 'padding:6px 10px;border-bottom:1px solid #e5e7eb;font-size:14px;';
const row = (a, b) => "<tr><td style='" + td + "color:#4b5563;'>" + esc(a) + "</td><td style='" + td + "text-align:right;font-weight:600;'>" + esc(b) + '</td></tr>';
const list = (items) => items.length
  ? "<ul style='margin:6px 0 0 18px;padding:0;font-size:14px;'>" + items.map((x) => '<li>' + esc(x.uid) + ' (' + esc(x.why) + ')</li>').join('') + '</ul>'
  : "<p style='margin:6px 0 0;font-size:14px;color:#4b5563;'>None.</p>";
const h = (t) => "<h3 style='margin:20px 0 0;font-size:13px;text-transform:uppercase;color:#00838F;'>" + t + '</h3>';
const html = "<div style='font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;color:#111827;'>"
  + "<p style='margin:0;font-size:15px;'>Caregivers texted for " + esc(date || '?') + ': old workflow vs new service (dry run).</p>'
  + (planned
    ? "<table style='width:100%;border-collapse:collapse;margin-top:10px;'>"
      + row('Old: texted (sheet status set, not ERROR)', oldTexted.length)
      + row('Old: marked ERROR', Object.keys(old).filter((u) => old[u].error && !old[u].texted).length)
      + row('New: would text', planned.length)
      + row('Both', same)
      + '</table>'
      + h('Only the old workflow texted') + list(onlyOld)
      + h('Only the new service would text') + list(onlyNew)
    : "<p style='margin:10px 0 0;font-size:14px;'>Not available: the reminders service did not return plannedCaregiverUids. Redeploy reminders from main.</p>")
  + "<p style='margin:22px 0 0;font-size:12px;color:#6b7280;'>Sheet rows for this date: " + rowsForDate + '. The new side is checked at run time, about 90 minutes after the old send, so a visit added in between shows as only new. Caregiver IDs only: no names, phone numbers or message text. Execution ' + esc($execution.id) + '.</p>'
  + '</div>';
return [{ json: { subject, html } }];

const j = $('Run Dry Run').first().json;
const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const detail = typeof j.error === 'string' ? j.error : (j.error && j.error.message ? j.error.message : 'No detail returned (the service may not have responded).');
const html = "<div style='font-family:Arial,Helvetica,sans-serif;max-width:560px;'><p>The shadow comparison could not run: the reminders dry run did not succeed.</p><p>" + esc(detail) + "</p><p style='font-size:12px;color:#6b7280;'>Execution " + esc($execution.id) + ". No names, phone numbers or message text.</p></div>";
return [{ json: { subject: '[RAH Reminders] Compare FAILED: dry run did not succeed', html } }];

